<?php require 'config/database.php'; if(!empty($_SESSION['user'])){header('Location: dashboard.php');exit;} $err='';
if($_SERVER['REQUEST_METHOD']==='POST'){$q=$pdo->prepare('SELECT * FROM users WHERE username=? AND status=1');$q->execute([trim(isset($_POST['username']) ? $_POST['username'] : '')]);$u=$q->fetch(PDO::FETCH_ASSOC);if($u && password_verify(isset($_POST['password']) ? $_POST['password'] : '',$u['password_hash'])){$_SESSION['user']=['id'=>$u['id'],'name'=>$u['nama_lengkap'],'role'=>$u['role']];header('Location: dashboard.php');exit;}$err='Username atau password tidak cocok.';}
?>
